package com.fittrack.storage;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import java.io.*;import java.nio.file.*;import java.util.UUID;
@Component public class FilePrivateObjectStorage implements PrivateObjectStorage {private final Path root;public FilePrivateObjectStorage(@Value("${app.storage-path}")String r){root=Path.of(r).toAbsolutePath().normalize();}public StoredObject put(String u,InputStream in,String t)throws IOException{Path x=root.resolve(u).resolve(UUID.randomUUID().toString()).normalize();if(!x.startsWith(root))throw new IOException("Invalid path");Files.createDirectories(x.getParent());long n=Files.copy(in,x);return new StoredObject(root.relativize(x).toString().replace('\\','/'),t,n);}public void delete(String u,String k)throws IOException{Path base=root.resolve(u).normalize(),x=k.replace('\\','/').startsWith(u+"/")?root.resolve(k).normalize():base.resolve(k).normalize();if(!x.startsWith(root)||!x.startsWith(base))throw new IOException("Invalid path");Files.deleteIfExists(x);}}
